a = [0] + a + [2 * 10 ** 9]

min_r = n
for i in range(n, 0, -1):
    if a[i] <= a[i + 1]:
        min_r = i
    else:
        break

ans = 0
right = min_r - 1
for left in range(1, n + 1):
    right = max(right, left)
    while right <= n and a[right + 1] < a[left - 1]:
        right += 1
    ans += n - right + 1
    if a[left] < a[left - 1]:
        break

print(ans)
```
