import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n + 2];
        // 读入数据并设置哨兵
        a[0] = 0;                  // 左哨兵
        a[n + 1] = 2000000000;     // 右哨兵
        for (int i = 1; i <= n; i++) {
            a[i] = sc.nextInt();
        }

        // 预处理最长非递减后缀起始位置
        int minR = n;
        for (int i = n; i >= 1; i--) {
            if (a[i] <= a[i + 1]) {
                minR = i;
            } else {
                break;
            }
        }

        long ans = 0;
        int right = minR - 1;
        for (int left = 1; left <= n; left++) {
            right = Math.max(right, left);
            while (right <= n && a[right + 1] < a[left - 1]) {
                right++;
            }
            ans += n - right + 1;
            if (a[left] < a[left - 1]) {
                break;
            }
        }

        System.out.println(ans);
        sc.close();
    }
}
